import json
import logging
import os
import time
import uuid

from fastapi import FastAPI, HTTPException, Request
from pydantic import BaseModel, Field

from app.resilience import AllProvidersFailed, FallbackClient, Provider


class JsonFormatter(logging.Formatter):
    """One JSON object per line: easy to ship to any log backend."""

    def format(self, record: logging.LogRecord) -> str:
        payload = {"ts": round(time.time(), 3), "level": record.levelname, "msg": record.getMessage()}
        payload.update(getattr(record, "fields", {}))
        return json.dumps(payload)


handler = logging.StreamHandler()
handler.setFormatter(JsonFormatter())
log = logging.getLogger("assistant")
log.addHandler(handler)
log.setLevel(os.getenv("LOG_LEVEL", "INFO").upper())

app = FastAPI()
START = time.time()


def make_fake_provider(name: str):
    """Stand-in so the service runs end to end. Replace the body with your SDK call and map its
    timeouts, 429s and 5xx to RetryableError, and 4xx validation errors to ProviderError."""

    def call(prompt: str, timeout: float) -> tuple[str, int, int]:
        text = f"[{name}] echo: {prompt[:80]}"
        return text, len(prompt) // 4, len(text) // 4  # (text, input_tokens, output_tokens), rough estimate

    return call


client = FallbackClient(
    providers=[Provider("primary", make_fake_provider("primary")), Provider("secondary", make_fake_provider("secondary"))],
    degraded=lambda prompt: "The assistant is temporarily limited. Here are the most relevant documents instead.",
)


class ChatIn(BaseModel):
    question: str = Field(min_length=1, max_length=4000)


@app.get("/healthz")
def healthz() -> dict:
    """Liveness: is the process able to answer? No dependency calls here."""
    return {"status": "ok", "uptime_s": round(time.time() - START, 1)}


@app.get("/readyz")
def readyz() -> dict:
    """Readiness: can this instance serve traffic? Check cheap local dependencies.
    Do NOT call the LLM provider here: a provider outage must not take every pod out of rotation."""
    # e.g. run SELECT 1 on the DB pool and PING on Redis; raise HTTPException(503) if either fails
    return {"status": "ready"}


@app.post("/chat")
def chat(body: ChatIn, request: Request) -> dict:
    request_id = request.headers.get("x-request-id", str(uuid.uuid4()))
    t0 = time.perf_counter()
    try:
        result = client.complete(body.question, timeout=float(os.getenv("LLM_TIMEOUT_SECONDS", "20")))
    except AllProvidersFailed:
        raise HTTPException(status_code=503, detail="temporarily unavailable")
    # log metadata, never the question or the answer text
    log.info(
        "chat_completed",
        extra={"fields": {
            "request_id": request_id,
            "provider": result.provider,
            "degraded": result.degraded,
            "input_tokens": result.input_tokens,
            "output_tokens": result.output_tokens,
            "latency_ms": round((time.perf_counter() - t0) * 1000),
            "question_chars": len(body.question),
        }},
    )
    return {"answer": result.text, "degraded": result.degraded, "request_id": request_id}

import threading
import time
from dataclasses import dataclass, field
from typing import Callable, Optional


class ProviderError(Exception):
    """Non-retryable provider failure (bad request, auth). Does not trip the breaker."""


class RetryableError(ProviderError):
    """Timeouts, 429, 5xx. Retried, and counted by the circuit breaker."""


class AllProvidersFailed(Exception):
    pass


class CircuitBreaker:
    """closed -> open after N consecutive failures -> half_open after reset_after seconds
    -> one probe call decides: success closes, failure re-opens."""

    def __init__(self, failure_threshold: int = 5, reset_after: float = 30.0,
                 clock: Callable[[], float] = time.monotonic):
        self.failure_threshold = failure_threshold
        self.reset_after = reset_after
        self.clock = clock
        self._failures = 0
        self._opened_at: Optional[float] = None
        self._probe_in_flight = False
        self._lock = threading.Lock()

    @property
    def state(self) -> str:
        if self._opened_at is None:
            return "closed"
        if self.clock() - self._opened_at >= self.reset_after:
            return "half_open"
        return "open"

    def allow(self) -> bool:
        with self._lock:
            state = self.state
            if state == "closed":
                return True
            if state == "open":
                return False
            if self._probe_in_flight:  # half_open: exactly one probe at a time
                return False
            self._probe_in_flight = True
            return True

    def record_success(self) -> None:
        with self._lock:
            self._failures = 0
            self._opened_at = None
            self._probe_in_flight = False

    def record_failure(self) -> None:
        with self._lock:
            self._probe_in_flight = False
            self._failures += 1
            if self._opened_at is not None or self._failures >= self.failure_threshold:
                self._opened_at = self.clock()  # (re)open and restart the cool-down


@dataclass
class Provider:
    name: str
    call: Callable[[str, float], tuple]  # (prompt, timeout) -> (text, input_tokens, output_tokens)
    breaker: CircuitBreaker = field(default_factory=CircuitBreaker)


@dataclass
class Result:
    text: str
    provider: str
    degraded: bool = False
    input_tokens: int = 0
    output_tokens: int = 0


class FallbackClient:
    def __init__(self, providers: list, degraded: Optional[Callable[[str], str]] = None,
                 max_attempts: int = 2, backoff: float = 0.2,
                 sleep: Callable[[float], None] = time.sleep):
        self.providers = providers
        self.degraded = degraded
        self.max_attempts = max_attempts
        self.backoff = backoff
        self.sleep = sleep

    def complete(self, prompt: str, timeout: float = 20.0) -> Result:
        for provider in self.providers:
            if not provider.breaker.allow():
                continue  # open circuit: skip instantly instead of waiting for a timeout
            for attempt in range(self.max_attempts):
                try:
                    text, tokens_in, tokens_out = provider.call(prompt, timeout)
                except RetryableError:
                    provider.breaker.record_failure()
                    if attempt + 1 < self.max_attempts:
                        self.sleep(self.backoff * (2 ** attempt))  # add random jitter in production
                        continue
                    break  # out of attempts: try next provider
                except ProviderError:
                    # our bug or a bad request: retrying or switching provider will not help the caller
                    provider.breaker.record_success()  # the provider itself is healthy
                    raise
                provider.breaker.record_success()
                return Result(text, provider.name, False, tokens_in, tokens_out)
        if self.degraded is not None:
            return Result(self.degraded(prompt), "degraded", True)
        raise AllProvidersFailed("no provider available")

import threading
import time


class FakeRedis:
    """In-memory stand-in for the redis-py subset we use. Values are strings."""

    def __init__(self, clock=time.monotonic):
        self.clock = clock
        self.down = False
        self._data = {}
        self._exp = {}
        self._lock = threading.Lock()

    def _guard(self):
        if self.down:
            raise ConnectionError("redis is down")

    def _purge(self, key):
        exp = self._exp.get(key)
        if exp is not None and exp <= self.clock():
            self._data.pop(key, None)
            self._exp.pop(key, None)

    def get(self, key):
        with self._lock:
            self._guard()
            self._purge(key)
            return self._data.get(key)

    def set(self, key, value, ex=None, nx=False):
        with self._lock:
            self._guard()
            self._purge(key)
            if nx and key in self._data:
                return None
            self._data[key] = str(value)
            if ex is not None:
                self._exp[key] = self.clock() + ex
            else:
                self._exp.pop(key, None)
            return True

    def delete(self, *keys):
        with self._lock:
            self._guard()
            n = 0
            for k in keys:
                self._purge(k)
                n += 1 if self._data.pop(k, None) is not None else 0
                self._exp.pop(k, None)
            return n

    def incr(self, key):
        with self._lock:
            self._guard()
            self._purge(key)
            value = int(self._data.get(key, "0")) + 1
            self._data[key] = str(value)
            return value

    def expire(self, key, seconds):
        with self._lock:
            self._guard()
            self._purge(key)
            if key not in self._data:
                return False
            self._exp[key] = self.clock() + seconds
            return True

    def ttl(self, key):
        with self._lock:
            self._guard()
            self._purge(key)
            if key not in self._data:
                return -2
            exp = self._exp.get(key)
            return -1 if exp is None else int(exp - self.clock())

    def token_bucket(self, key, rate, capacity, cost):
        """Python mirror of the Lua script in guards.LUA_TOKEN_BUCKET."""
        with self._lock:
            self._guard()
            now = self.clock()
            tokens, stamp = capacity, now
            if key in self._data:
                tokens, stamp = (float(x) for x in self._data[key].split(":"))
            tokens = min(capacity, tokens + max(0.0, now - stamp) * rate)
            allowed = tokens >= cost
            if allowed:
                tokens -= cost
            self._data[key] = f"{tokens}:{now}"
            return 1 if allowed else 0

import hashlib
import json
import threading


class _Flight:
    def __init__(self):
        self.event = threading.Event()
        self.value = None
        self.ok = False


class AnswerCache:
    """Tenant-namespaced cache with TTL, generation-based invalidation,
    in-process single-flight and graceful degradation when Redis fails."""

    def __init__(self, redis, ttl=3600, prefix="app"):
        self.r = redis
        self.ttl = ttl
        self.prefix = prefix
        self._flights = {}
        self._mu = threading.Lock()
        self.hits = 0
        self.misses = 0
        self.degraded = 0

    def _gen_key(self, tenant):
        return f"{self.prefix}:{tenant}:gen"

    def make_key(self, tenant, kind, scope, payload, gen):
        body = json.dumps(payload, sort_keys=True, separators=(",", ":"))
        digest = hashlib.sha256(body.encode()).hexdigest()[:32]
        return f"{self.prefix}:{tenant}:g{gen}:{kind}:{scope}:{digest}"

    def invalidate_tenant(self, tenant):
        """Bump the generation: every old key becomes unreachable and ages out via TTL."""
        return self.r.incr(self._gen_key(tenant))

    def get_or_compute(self, tenant, kind, scope, payload, compute, ttl=None):
        try:
            gen = int(self.r.get(self._gen_key(tenant)) or 0)
            key = self.make_key(tenant, kind, scope, payload, gen)
            hit = self.r.get(key)
        except ConnectionError:
            self.degraded += 1
            return compute()
        if hit is not None:
            self.hits += 1
            return json.loads(hit)
        self.misses += 1
        with self._mu:
            flight = self._flights.get(key)
            leader = flight is None
            if leader:
                flight = self._flights[key] = _Flight()
        if not leader:
            flight.event.wait(timeout=30)
            return flight.value if flight.ok else compute()
        try:
            value = compute()
            flight.value, flight.ok = value, True
            try:
                self.r.set(key, json.dumps(value), ex=ttl or self.ttl)
            except ConnectionError:
                self.degraded += 1
            return value
        finally:
            with self._mu:
                self._flights.pop(key, None)
            flight.event.set()

import threading
import time

import pytest

from ai_cache import AnswerCache
from fake_redis import FakeRedis
from guards import Idempotency, InProgress, KeyReuse, TokenBucketLimiter, idempotent


class Clock:
    def __init__(self):
        self.t = 1000.0

    def __call__(self):
        return self.t


@pytest.fixture
def clock():
    return Clock()


@pytest.fixture
def r(clock):
    return FakeRedis(clock=clock)


def test_cache_hit_and_ttl(r, clock):
    cache, calls = AnswerCache(r, ttl=60), []
    fn = lambda: calls.append(1) or {"a": "x"}
    assert cache.get_or_compute("t1", "ans", "acl:eng", {"q": "hi"}, fn) == {"a": "x"}
    assert cache.get_or_compute("t1", "ans", "acl:eng", {"q": "hi"}, fn) == {"a": "x"}
    assert len(calls) == 1 and cache.hits == 1
    clock.t += 61
    cache.get_or_compute("t1", "ans", "acl:eng", {"q": "hi"}, fn)
    assert len(calls) == 2


def test_tenants_and_scopes_never_share_entries(r):
    cache = AnswerCache(r)
    a = cache.get_or_compute("t1", "ans", "user:1", {"q": "q"}, lambda: "t1-u1")
    b = cache.get_or_compute("t2", "ans", "user:1", {"q": "q"}, lambda: "t2-u1")
    c = cache.get_or_compute("t1", "ans", "user:2", {"q": "q"}, lambda: "t1-u2")
    assert (a, b, c) == ("t1-u1", "t2-u1", "t1-u2")


def test_invalidate_tenant_bumps_generation(r):
    cache, n = AnswerCache(r), [0]

    def fn():
        n[0] += 1
        return n[0]

    assert cache.get_or_compute("t1", "ans", "s", {"q": 1}, fn) == 1
    assert cache.get_or_compute("t1", "ans", "s", {"q": 1}, fn) == 1
    cache.invalidate_tenant("t1")
    assert cache.get_or_compute("t1", "ans", "s", {"q": 1}, fn) == 2


def test_single_flight_runs_compute_once(r):
    cache, n, gate = AnswerCache(r), [0], threading.Event()

    def slow():
        n[0] += 1
        gate.wait(2)
        return "done"

    results = []
    threads = [threading.Thread(target=lambda: results.append(
        cache.get_or_compute("t1", "ans", "s", {"q": "same"}, slow))) for _ in range(5)]
    for t in threads:
        t.start()
    time.sleep(0.2)
    gate.set()
    for t in threads:
        t.join()
    assert n[0] == 1 and results == ["done"] * 5


def test_cache_degrades_when_redis_down(r):
    cache = AnswerCache(r)
    r.down = True
    assert cache.get_or_compute("t1", "ans", "s", {"q": 1}, lambda: "live") == "live"
    assert cache.degraded == 1


def test_token_bucket_burst_refill_and_fail_open(r, clock):
    lim = TokenBucketLimiter(r, rate=1.0, capacity=3)
    assert [lim.allow("t1", "u1") for _ in range(4)] == [True, True, True, False]
    assert lim.allow("t1", "u2") is True  # separate bucket
    clock.t += 2
    assert [lim.allow("t1", "u1") for _ in range(3)] == [True, True, False]
    r.down = True
    assert lim.allow("t1", "u1") is True
    assert TokenBucketLimiter(r, 1.0, 3, fail_open=False).allow("t1", "u1") is False


def test_idempotency_replay_conflict_failure_and_in_progress(r):
    calls = []

    @idempotent(Idempotency(r))
    def create(tenant, body):
        calls.append(body)
        return {"id": len(calls)}

    assert create("t1", "k1", {"x": 1}) == {"id": 1}
    assert create("t1", "k1", {"x": 1}) == {"id": 1}
    assert len(calls) == 1
    with pytest.raises(KeyReuse):
        create("t1", "k1", {"x": 2})
    store = Idempotency(r)

    def boom(_):
        raise RuntimeError("provider 500")

    with pytest.raises(RuntimeError):
        store.run("t1", "k2", {"y": 1}, boom)
    assert store.run("t1", "k2", {"y": 1}, lambda b: "ok") == "ok"
    r.set("idem:t1:k3", '{"state": "pending", "fp": "' + __import__("hashlib").sha256(
        b'{"z": 1}').hexdigest() + '"}', ex=60)
    with pytest.raises(InProgress):
        store.run("t1", "k3", {"z": 1}, lambda b: "never")

