-- Postgres 16 + pgvector. Pooled multi-tenancy with row-level security.
CREATE EXTENSION IF NOT EXISTS vector;

CREATE TABLE documents (
  id            bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  tenant_id     uuid        NOT NULL,
  source_id     uuid        NOT NULL,
  external_id   text        NOT NULL,           -- id in Drive, Confluence, S3 ...
  title         text        NOT NULL,
  url           text        NOT NULL,           -- deep link used for citations
  status        text        NOT NULL DEFAULT 'active' CHECK (status IN ('active','deleted')),
  source_version bigint     NOT NULL,           -- source modified time or revision; rejects stale events
  live_version  int         NOT NULL DEFAULT 0, -- chunks of this version are the visible ones
  content_hash  text        NOT NULL,
  acl           text[]      NOT NULL DEFAULT '{}', -- principals: 'user:42', 'group:eng', 'tenant:*'
  deleted_at    timestamptz,
  updated_at    timestamptz NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, source_id, external_id)
);

CREATE TABLE chunks (
  id          bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  tenant_id   uuid   NOT NULL,                  -- duplicated so RLS needs no join
  document_id bigint NOT NULL REFERENCES documents(id) ON DELETE CASCADE,
  doc_version int    NOT NULL,
  ord         int    NOT NULL,
  heading     text,
  body        text   NOT NULL,
  text_hash   text   NOT NULL,                  -- embedding cache key with model version
  acl         text[] NOT NULL,                  -- copy of documents.acl, kept in sync
  embedding   halfvec(1024) NOT NULL,           -- 2 bytes per dim; model version tracked in table name or column
  tsv         tsvector GENERATED ALWAYS AS (to_tsvector('english', coalesce(heading,'') || ' ' || body)) STORED,
  UNIQUE (document_id, doc_version, ord)
);

CREATE INDEX chunks_embedding_hnsw ON chunks USING hnsw (embedding halfvec_cosine_ops);
CREATE INDEX chunks_tsv_gin        ON chunks USING gin (tsv);
CREATE INDEX chunks_acl_gin        ON chunks USING gin (acl);
CREATE INDEX chunks_tenant_doc     ON chunks (tenant_id, document_id);

-- Row-level security: every query is scoped to the tenant set by the application on this transaction.
ALTER TABLE documents ENABLE ROW LEVEL SECURITY;
ALTER TABLE chunks    ENABLE ROW LEVEL SECURITY;
ALTER TABLE documents FORCE ROW LEVEL SECURITY;   -- applies even to the table owner
ALTER TABLE chunks    FORCE ROW LEVEL SECURITY;

CREATE POLICY tenant_isolation ON documents
  USING (tenant_id = current_setting('app.tenant_id')::uuid);
CREATE POLICY tenant_isolation ON chunks
  USING (tenant_id = current_setting('app.tenant_id')::uuid);

-- The app connects as a role that is neither owner nor superuser (superusers bypass RLS):
-- CREATE ROLE app_rw LOGIN; GRANT SELECT, INSERT, UPDATE, DELETE ON documents, chunks TO app_rw;
-- In each transaction: SET LOCAL app.tenant_id = '<tenant uuid>';   -- SET LOCAL, so pooled connections never leak it

import re


def rrf(rankings: list, k: int = 60) -> list:
    """Reciprocal rank fusion. Each ranking is a list of ids, best first. Returns [(id, score)]."""
    scores: dict = {}
    for ranking in rankings:
        for rank, item in enumerate(ranking, start=1):
            scores[item] = scores.get(item, 0.0) + 1.0 / (k + rank)
    return sorted(scores.items(), key=lambda kv: (-kv[1], kv[0]))


def authorized(chunk_acl: set, principals: set) -> bool:
    """Defence in depth: re-check permission after retrieval and before building the prompt."""
    return bool(chunk_acl & principals)


def fit_budget(chunks: list, max_tokens: int) -> list:
    """chunks: [(id, tokens)], best first. Keep the best that fit the context budget."""
    kept, used = [], 0
    for cid, tokens in chunks:
        if used + tokens <= max_tokens:
            kept.append(cid)
            used += tokens
    return kept


def verify_citations(answer: str, context_ids: list) -> dict:
    """Citations look like [1], [2] and refer to positions in the context list we sent."""
    cited = {int(n) for n in re.findall(r"\[(\d+)\]", answer)}
    valid = {n for n in cited if 1 <= n <= len(context_ids)}
    return {
        "cited": sorted(cited),
        "invalid": sorted(cited - valid),          # model cited a source we never gave it
        "has_citation": bool(valid),
        "sources": [context_ids[n - 1] for n in sorted(valid)],
    }


def check() -> None:
    vec = ["a", "b", "c", "d"]
    kw = ["c", "a", "e"]
    fused = [i for i, _ in rrf([vec, kw])]
    assert fused[:2] == ["a", "c"]                 # appears high in both lists
    assert set(fused) == {"a", "b", "c", "d", "e"}

    assert authorized({"group:eng"}, {"user:1", "group:eng"})
    assert not authorized({"group:hr"}, {"user:1", "group:eng"})

    assert fit_budget([("x", 500), ("y", 700), ("z", 300)], 900) == ["x", "z"]

    ok = verify_citations("Refunds take 5 days [1]. Escalate to support [2].", ["doc7#3", "doc9#1"])
    assert ok["sources"] == ["doc7#3", "doc9#1"] and not ok["invalid"]
    bad = verify_citations("Refunds take 5 days [4].", ["doc7#3"])
    assert bad["invalid"] == [4] and not bad["has_citation"]
    print("retrieval helpers: all checks passed")


if __name__ == "__main__":
    check()

import uuid
from dataclasses import dataclass, field
from datetime import date, timedelta
from typing import Optional


@dataclass
class Order:
    id: str
    user_id: str
    total_cents: int
    delivered_on: date
    refunded_cents: int = 0


class OrderStore:
    def __init__(self, orders):
        self._orders = {o.id: o for o in orders}

    def search(self, user_id: str, order_id: Optional[str] = None) -> list:
        """The user id comes from the authenticated session, never from model arguments."""
        found = [o for o in self._orders.values() if o.user_id == user_id]
        return [o for o in found if order_id is None or o.id == order_id]

    def get(self, order_id: str) -> Optional[Order]:
        return self._orders.get(order_id)


class PaymentGateway:
    """Fake payment provider; real ones accept an idempotency key."""

    def __init__(self):
        self.executed = {}

    def refund(self, order: Order, amount_cents: int, idempotency_key: str) -> str:
        if idempotency_key in self.executed:
            return self.executed[idempotency_key]
        order.refunded_cents += amount_cents
        ref = f"re_{len(self.executed) + 1}"
        self.executed[idempotency_key] = ref
        return ref


RETURN_WINDOW_DAYS = 30


def check_refund_policy(order: Order, amount_cents: int, today: date) -> Optional[str]:
    """Pure policy: a rejection reason, or None."""
    if amount_cents <= 0:
        return "amount must be positive"
    if amount_cents > order.total_cents - order.refunded_cents:
        return "amount exceeds the refundable balance"
    if today - order.delivered_on > timedelta(days=RETURN_WINDOW_DAYS):
        return "outside the 30 day return window"
    return None


@dataclass
class Approval:
    id: str
    order_id: str
    user_id: str
    amount_cents: int
    reason: str
    status: str = "pending"        # pending | approved | rejected
    refund_ref: Optional[str] = None
    decided_by: Optional[str] = None


@dataclass
class SupportTools:
    store: OrderStore
    payments: PaymentGateway
    today: date
    approvals: dict = field(default_factory=dict)
    by_key: dict = field(default_factory=dict)
    audit: list = field(default_factory=list)

    def request_refund(self, session_user: str, order_id: str, amount_cents: int,
                       reason: str, idempotency_key: str) -> Approval:
        """Tool exposed to the model. It can only create a pending request, never move money."""
        if idempotency_key in self.by_key:
            return self.by_key[idempotency_key]
        mine = self.store.search(session_user, order_id)
        if not mine:
            raise PermissionError("order not found for this user")
        problem = check_refund_policy(mine[0], amount_cents, self.today)
        if problem:
            raise ValueError(problem)
        approval = Approval(str(uuid.uuid4()), order_id, session_user, amount_cents, reason[:500])
        self.approvals[approval.id] = approval
        self.by_key[idempotency_key] = approval
        self.audit.append(("requested", approval.id, session_user))
        return approval

    def decide(self, approval_id: str, approver: str, approve: bool) -> Approval:
        """Human review UI calls this; policy is re-checked because state may have changed."""
        a = self.approvals[approval_id]
        if a.status != "pending":
            return a  # idempotent
        order = self.store.get(a.order_id)
        if approve and check_refund_policy(order, a.amount_cents, self.today) is None:
            a.refund_ref = self.payments.refund(order, a.amount_cents, f"approval:{a.id}")
            a.status = "approved"
        else:
            a.status = "rejected"
        a.decided_by = approver
        self.audit.append((a.status, a.id, approver))
        return a


def next_state(state: str, event: str) -> str:
    """Anything unexpected escalates to a human."""
    table = {
        ("GATHER", "order_identified"): "PROPOSE",
        ("PROPOSE", "user_confirmed"): "AWAITING_APPROVAL",
        ("PROPOSE", "user_declined"): "DONE",
        ("AWAITING_APPROVAL", "approved"): "DONE",
        ("AWAITING_APPROVAL", "rejected"): "DONE",
    }
    if event in ("injection_flagged", "user_angry", "tool_error_twice", "step_limit"):
        return "ESCALATED"
    return table.get((state, event), "ESCALATED")


def check() -> None:
    today = date(2026, 3, 1)
    store = OrderStore([Order("o1", "alice", 5000, date(2026, 2, 20)),
                        Order("o2", "alice", 5000, date(2025, 12, 1)),
                        Order("o3", "bob", 9000, date(2026, 2, 25))])
    pay = PaymentGateway()
    tools = SupportTools(store, pay, today)

    a = tools.request_refund("alice", "o1", 2000, "damaged", "k1")
    assert a.status == "pending" and pay.executed == {}                 # no money moved yet
    assert tools.request_refund("alice", "o1", 2000, "damaged", "k1") is a   # retry is idempotent

    for bad in [("alice", "o3", 100), ("alice", "o2", 100), ("alice", "o1", 6000)]:
        try:
            tools.request_refund(*bad[:2], bad[2], "x", "k-" + bad[1])
            raise AssertionError("should have been rejected")
        except (PermissionError, ValueError):
            pass

    done = tools.decide(a.id, "agent-7", True)
    assert done.status == "approved" and store.get("o1").refunded_cents == 2000
    tools.decide(a.id, "agent-7", True)                                 # double click
    assert len(pay.executed) == 1 and store.get("o1").refunded_cents == 2000

    assert next_state("GATHER", "order_identified") == "PROPOSE"
    assert next_state("PROPOSE", "injection_flagged") == "ESCALATED"
    assert next_state("GATHER", "user_confirmed") == "ESCALATED"        # impossible transition
    print("support agent: all checks passed")


if __name__ == "__main__":
    check()

import os
import re

# name -> allowed subcommands (None means no subcommand) and allowed flags
ALLOWED = {
    "pytest": {"sub": None, "flags": {"-q", "-x", "-k", "--maxfail"}},
    "ruff": {"sub": {"check"}, "flags": {"--select"}},
    "git": {"sub": {"diff", "status", "log"}, "flags": {"--stat", "-n"}},
}
SHELL_META = re.compile(r"[;&|`$<>\n]")


def is_allowed(argv: list, workdir: str, repo_root: str) -> tuple:
    """Gate for a codebase assistant. Commands also run in a sandbox with no network and no secrets;
    this check is one layer, never the only one."""
    if not argv:
        return False, "empty command"
    name = os.path.basename(argv[0])
    rule = ALLOWED.get(name)
    if rule is None:
        return False, f"{name} is not on the allowlist"
    root = os.path.realpath(repo_root)
    first_positional = True
    for token in argv[1:]:
        if SHELL_META.search(token):
            return False, "shell metacharacters are not allowed"
        if token.startswith("-"):
            if token.split("=")[0] not in rule["flags"]:
                return False, f"flag {token} not allowed"
            continue
        if rule["sub"] is not None and first_positional:
            if token not in rule["sub"]:
                return False, f"subcommand {token} not allowed"
            first_positional = False
            continue
        first_positional = False
        if "/" in token or token.startswith(".."):
            path = os.path.realpath(os.path.join(workdir, token))
            if not path.startswith(root + os.sep):
                return False, "path escapes the repository"
    if rule["sub"] is not None and first_positional:
        return False, "a subcommand is required"
    return True, "ok"


def check() -> None:
    root = "/work/repo"
    assert is_allowed(["pytest", "-q", "tests/test_a.py"], root, root)[0]
    assert is_allowed(["git", "diff", "--stat"], root, root)[0]
    assert not is_allowed(["curl", "http://evil.test"], root, root)[0]
    assert not is_allowed(["pytest", "-q; rm -rf /"], root, root)[0]
    assert not is_allowed(["pytest", "../../etc/passwd"], root, root)[0]
    assert not is_allowed(["git", "push"], root, root)[0]
    assert not is_allowed(["git"], root, root)[0]
    assert not is_allowed(["pytest", "--rootdir=/"], root, root)[0]
    print("safe exec: all checks passed")


if __name__ == "__main__":
    check()
